; ============================================================
; sub update (turbo mode)
; ============================================================

p_sfx_update:

			; Sfx.cls 56: Dim i As Integer, v As Integer, p As Integer

			; Sfx.cls 57: mix = &H3F
			dw kw_ltov, 63, var_sfx_mix

			; Sfx.cls 58: For i = 0 To 2
			dw kw_ztov, var_sfx_update_i
for131_t:

			; Sfx.cls 59: If left(i) > 0 Then
			dw kw_aget, arr_sfx_left, var_sfx_update_i, tmp0
			dw kw_scpgtvl, tmp0, 0
			dw kw_goto_iffalse, if132_1

			; Sfx.cls 60: v = (vol(i) * left(i) + total(i) - 1) \ total(i)
			dw kw_aget, arr_sfx_vol, var_sfx_update_i, tmp0
			dw kw_aget, arr_sfx_left, var_sfx_update_i, tmp1
			dw kw_mulvv, tmp0, tmp1, tmp0
			dw kw_aget, arr_sfx_total, var_sfx_update_i, tmp1
			dw kw_add, tmp0, tmp1, tmp0
			dw kw_dec, tmp0
			dw kw_aget, arr_sfx_total, var_sfx_update_i, tmp1
			dw kw_divvv, tmp0, tmp1, var_sfx_update_v

			; Sfx.cls 61: p = per(i)
			dw kw_aget, arr_sfx_per, var_sfx_update_i, var_sfx_update_p

			; Sfx.cls 62: If nse(i) Then
			dw kw_aget, arr_sfx_nse, var_sfx_update_i, tmp0
			dw kw_goto_ifzero, tmp0, if133_1

			; Sfx.cls 63: W 6, p And 31
			dw kw_andvl, var_sfx_update_p, 31, tmp1
			dw fn_sfx_w, lit_6, tmp1

			; Sfx.cls 64: mix = mix And Not (8 * (2 ^ i))
			dw kw_pow, lit_2, var_sfx_update_i, tmp2
			dw kw_mulvl, tmp2, 8, tmp1
			dw kw_notv, tmp1, tmp1
			dw kw_andvv, var_sfx_mix, tmp1, var_sfx_mix

			; Sfx.cls 65: Else
			dw if133_e_go
if133_1:

			; Sfx.cls 66: W i * 2, p And 255
			dw kw_2x, var_sfx_update_i, tmp0
			dw kw_andvl, var_sfx_update_p, 255, tmp1
			dw fn_sfx_w, tmp0, tmp1

			; Sfx.cls 67: W i * 2 + 1, (p \ 256) And 15
			dw kw_2x, var_sfx_update_i, tmp0
			dw kw_inc, tmp0
			dw kw_divvl, var_sfx_update_p, 256, tmp1
			dw kw_andvl, tmp1, 15, tmp1
			dw fn_sfx_w, tmp0, tmp1

			; Sfx.cls 68: mix = mix And Not (2 ^ i)
			dw kw_pow, lit_2, var_sfx_update_i, tmp1
			dw kw_notv, tmp1, tmp1
			dw kw_andvv, var_sfx_mix, tmp1, var_sfx_mix

			; Sfx.cls 69: End If
if133_e:

			; Sfx.cls 70: W 8 + i, v
			dw kw_addl, var_sfx_update_i, 8, tmp0
			dw fn_sfx_w, tmp0, var_sfx_update_v

			; Sfx.cls 71: per(i) = per(i) + slide(i)
			dw kw_aget, arr_sfx_per, var_sfx_update_i, tmp1
			dw kw_aget, arr_sfx_slide, var_sfx_update_i, tmp2
			dw kw_add, tmp1, tmp2, tmp1
			dw kw_aset, arr_sfx_per, var_sfx_update_i, tmp1

			; Sfx.cls 72: If per(i) < 1 Then per(i) = 1
			dw kw_aget, arr_sfx_per, var_sfx_update_i, tmp0
			dw kw_scpltvl, tmp0, 1
			dw kw_goto_iffalse, if134_1
			dw kw_asetl, arr_sfx_per, var_sfx_update_i, 1
if134_1:

			; Sfx.cls 73: left(i) = left(i) - 1
			dw kw_aget, arr_sfx_left, var_sfx_update_i, tmp1
			dw kw_dec, tmp1
			dw kw_aset, arr_sfx_left, var_sfx_update_i, tmp1

			; Sfx.cls 74: Else
			dw if132_e_go
if132_1:

			; Sfx.cls 75: W 8 + i, 0
			dw kw_addl, var_sfx_update_i, 8, tmp0
			dw fn_sfx_w, tmp0, lit_0

			; Sfx.cls 76: End If
if132_e:

			; Sfx.cls 77: Next
			dw kw_next1l, var_sfx_update_i, 2, for131_t
for131_e:

			; Sfx.cls 78: W 7, mix
			dw fn_sfx_w, lit_7, var_sfx_mix
			dw p_sfx_update_r

